from pathlib import Path
import runpy
app=runpy.run_path(str(Path.cwd()/'src/storage.py'))
failure=OSError('Private path /srv/private/customer-42/inventory.db unavailable')
class Store:
    def load(self): raise failure
try: app['load_inventory'](Store())
except app['InventoryError'] as error:
    assert error.__cause__ is failure
    assert app['error_message'](error)=='Inventory could not be loaded.'
else: raise AssertionError('storage failure was swallowed')
class Working:
    def load(self): return [{'name':'Tea','quantity':2}]
assert app['load_inventory'](Working())==[{'name':'Tea','quantity':2}]
